// Runs once for each page: apply deterministic SEO rules, no AI
const page = $json;
const findings = [];
const add = (rule, severity, label, message, value) =>
  findings.push({ rule, severity, label, message, value });

// 1. Title (Google shows about 60 characters)
const titleLength = page.title.length;
if (!titleLength) add('title_missing', 'high', 'issue', 'Page has no title', 0);
else if (titleLength > 60) add('title_too_long', 'medium', 'issue', 'Title is cut off in search results', titleLength);
else if (titleLength < 30) add('title_too_short', 'low', 'issue', 'Title is too short to describe the page', titleLength);

// 2. Meta description (Google shows about 160 characters)
const metaLength = page.meta_description.length;
if (!metaLength) add('meta_missing', 'high', 'issue', 'No meta description, Google picks its own snippet', 0);
else if (metaLength > 160) add('meta_too_long', 'medium', 'issue', 'Meta description is cut off in search results', metaLength);
else if (metaLength < 70) add('meta_too_short', 'low', 'issue', 'Meta description is too short to persuade', metaLength);

// 3. H1 (exactly one main heading)
if (page.h1_count === 0) add('h1_missing', 'high', 'issue', 'Page has no H1 heading', 0);
else if (page.h1_count > 1) add('h1_multiple', 'medium', 'issue', 'Page has more than one H1 heading', page.h1_count);

// 4. Canonical (should point to the page itself)
const normalize = (url) => (url || '').replace(/\/$/, '');
if (!page.canonical) add('canonical_missing', 'medium', 'issue', 'No canonical URL', 0);
else if (normalize(page.canonical) !== normalize(page.url)) add('canonical_other', 'low', 'question', 'Canonical points to a different URL', page.canonical);

// 5. Structured data (JSON-LD)
if (page.json_ld_count === 0) add('no_structured_data', 'medium', 'question', 'No JSON-LD structured data found', 0);

// 6. Image alt text (empty alt can be correct for decorative images)
if (page.img_missing_alt > 0) add('img_missing_alt', 'low', 'issue', 'Images without alt text', page.img_missing_alt);

return { json: {
  url: page.url,
  page_type: page.page_type,
  rule_findings: findings,
  rule_finding_count: findings.length
}};
